  "inlineSchema": "// Veltra API — Prisma schema\n// Node.js/NestJS + PostgreSQL. Timeline documents are stored as Json.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------------------------------------------------------------- enums ----\nenum Role {\n  USER\n  EDITOR\n  ADMIN\n}\n\nenum UserStatus {\n  ACTIVE\n  PENDING\n  SUSPENDED\n}\n\nenum ProjectStatus {\n  DRAFT\n  EDITING\n  RENDERING\n  EXPORTED\n  ARCHIVED\n}\n\nenum MediaKind {\n  VIDEO\n  AUDIO\n  IMAGE\n  STICKER\n  FONT\n}\n\nenum ExportStatus {\n  QUEUED\n  RENDERING\n  COMPLETE\n  FAILED\n}\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELED\n}\n\nenum PlatformContentStatus {\n  DRAFT\n  REVIEW\n  PUBLISHED\n  SCHEDULED\n}\n\nenum QuestionStatus {\n  OPEN\n  REPLIED\n  RESOLVED\n}\n\n// ---------------------------------------------------------------- models ----\nmodel User {\n  id              String     @id @default(cuid())\n  email           String     @unique\n  passwordHash    String?\n  fullName        String\n  avatarUrl       String?\n  role            Role       @default(USER)\n  status          UserStatus @default(PENDING)\n  emailVerifiedAt DateTime?\n  plan            Plan?      @relation(fields: [planId], references: [id])\n  planId          String?\n\n  projects     Project[]\n  mediaAssets  MediaAsset[]\n  exports      Export[]\n  subscription Subscription?\n  sessions     Session[]\n  loginEvents  LoginEvent[]\n  activities   Activity[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([role])\n  @@index([status])\n}\n\nmodel Session {\n  id          String   @id @default(cuid())\n  userId      String\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash   String\n  refreshHash String?\n  ipAddress   String?\n  userAgent   String?\n  expiresAt   DateTime\n  createdAt   DateTime @default(now())\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\nmodel LoginEvent {\n  id        String   @id @default(cuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  email     String\n  provider  String // EMAIL | GOOGLE | MAGIC_LINK\n  success   Boolean\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([createdAt])\n  @@index([email])\n}\n\nmodel Plan {\n  id            String         @id @default(cuid())\n  slug          String         @unique // free | pro | agency\n  name          String\n  priceCents    Int\n  interval      String // month | year\n  features      Json           @default(\"{}\")\n  active        Boolean        @default(true)\n  users         User[]\n  subscriptions Subscription[]\n  createdAt     DateTime       @default(now())\n\n  @@index([active])\n}\n\nmodel Subscription {\n  id                   String             @id @default(cuid())\n  userId               String             @unique\n  user                 User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  planId               String\n  plan                 Plan               @relation(fields: [planId], references: [id])\n  status               SubscriptionStatus @default(TRIALING)\n  stripeCustomerId     String?\n  stripeSubscriptionId String?            @unique\n  currentPeriodStart   DateTime?\n  currentPeriodEnd     DateTime?\n  cancelAtPeriodEnd    Boolean            @default(false)\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n\n  @@index([status])\n}\n\nmodel Project {\n  id            String        @id @default(cuid())\n  ownerId       String\n  owner         User          @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  templateId    String?\n  title         String\n  description   String?\n  status        ProjectStatus @default(EDITING)\n  durationSec   Int           @default(0)\n  sizeBytes     BigInt        @default(0)\n  timeline      Json          @default(\"{}\") // clips, tracks, captions, effects\n  thumbnailId   String?\n  collaborators Json          @default(\"[]\") // emails + roles\n\n  mediaAssets MediaAsset[]\n  exports     Export[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([ownerId])\n  @@index([status])\n  @@index([updatedAt])\n}\n\nmodel MediaAsset {\n  id          String    @id @default(cuid())\n  ownerId     String\n  owner       User      @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  projectId   String?\n  project     Project?  @relation(fields: [projectId], references: [id], onDelete: SetNull)\n  kind        MediaKind\n  fileName    String\n  mimeType    String\n  sizeBytes   BigInt\n  storageKey  String    @unique // object-storage key\n  width       Int?\n  height      Int?\n  durationSec Float?\n  meta        Json      @default(\"{}\")\n  createdAt   DateTime  @default(now())\n\n  @@index([ownerId])\n  @@index([projectId])\n}\n\nmodel Export {\n  id           String       @id @default(cuid())\n  projectId    String\n  project      Project      @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  userId       String\n  user         User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  status       ExportStatus @default(QUEUED)\n  resolution   String // 720p | 1080p | 2k | 4k\n  fps          Int          @default(30)\n  format       String // mp4 | webm | mov\n  outputUrl    String?\n  errorMessage String?\n  sizeBytes    BigInt?\n  durationSec  Int?\n  renderJobId  String?\n  startedAt    DateTime?\n  finishedAt   DateTime?\n  createdAt    DateTime     @default(now())\n\n  @@index([projectId])\n  @@index([status])\n  @@index([userId, createdAt])\n}\n\nmodel Page {\n  id          String                @id @default(cuid())\n  slug        String                @unique\n  title       String\n  contentJson Json                  @default(\"{}\")\n  status      PlatformContentStatus @default(DRAFT)\n  authorId    String?\n  updatedAt   DateTime              @updatedAt\n  createdAt   DateTime              @default(now())\n\n  @@index([status])\n}\n\nmodel BlogPost {\n  id          String                @id @default(cuid())\n  slug        String                @unique\n  title       String\n  excerpt     String?\n  bodyJson    Json                  @default(\"{}\")\n  tag         String?\n  coverKey    String?\n  status      PlatformContentStatus @default(DRAFT)\n  authorId    String?\n  publishedAt DateTime?\n  viewCount   Int                   @default(0)\n  createdAt   DateTime              @default(now())\n  updatedAt   DateTime              @updatedAt\n\n  @@index([status])\n  @@index([publishedAt])\n}\n\nmodel Question {\n  id        String         @id @default(cuid())\n  email     String\n  subject   String\n  message   String\n  priority  String         @default(\"MEDIUM\") // HIGH | MEDIUM | LOW\n  status    QuestionStatus @default(OPEN)\n  repliedAt DateTime?\n  createdAt DateTime       @default(now())\n\n  @@index([status])\n  @@index([createdAt])\n}\n\nmodel Activity {\n  id        String   @id @default(cuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  type      String // SIGNUP | EXPORT | PAYMENT | LOGIN | PROJECT_UPDATE\n  message   String\n  meta      Json     @default(\"{}\")\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([createdAt])\n}\n",
